  "bisir5": "సమకాలీకరించబడలేదుః సర్వర్ ఇంకా పొదుపు చరిత్రను అనుమతించదు. సైట్ యజమాని కొత్తదాన్ని దాటాలి. firebase-rules.json (\"హిస్టరీతో\") మరియు ప్రెస్ పబ్లిష్.",
  "1ger7zw": "సమకాలీకరించబడలేదు (ఆఫ్లైన్). ఆటలు ఈ పరికరంలో ఉంచబడతాయి మరియు తరువాత సమకాలీకరించబడతాయి.",
  "1tcqsow": "ఇంకా సమకాలీకరించబడలేదు, తరువాత తిరిగి ప్రారంభమవుతుంది.",
  "qdq1p4": "Googleతో సైన్ ఇన్ చేయండి",
  "69d7om": "అతిథిగా ఆడండి",
  "1wkzdj4": "అతిథులు కంప్యూటర్, 2-ప్లేయర్ గేమ్స్, పజిల్స్ మరియు పాఠాలు ఆడవచ్చు. ర్యాంక్ లేదు/ Eloఆన్లైన్ ప్లే లేదు, పోటీలు లేవు.",
  "1cngbzp": "వెల్కమ్! ఈ గూగుల్ ఖాతాకు డిస్ప్లే పేరును ఎంచుకోండి. ఇది లీడర్బోర్డ్లో కనిపిస్తుంది మరియు మార్చలేము.",
