  "2onl4m": "Gmail (సైట్ ప్రకటనలు, కొత్త పోటీలు, రిజిస్టర్డ్ పోటీలు ప్రారంభం వరకు) కు ఇమెయిల్ నోటిఫికేషన్లు",
  "6cre33": "Gmail ద్వారా నోటిఫికేషన్లను స్వీకరించడానికి గూగుల్తో సైన్ ఇన్ చేయండి.",
  "ebb134": "Gmail నోటిఫికేషన్లు మారాయి.",
  "3f2q55": "రక్షించకుండా, మీ సంబంధాన్ని తనిఖీ చేసి మళ్ళీ ప్రయత్నించండి.",
