  "rs79gz": "మీరు అతిథిగా ఆడుతున్నారు.",
  "c0tvt5": "ర్యాంక్ పొందడానికి (లేదా గూగుల్ను ఉపయోగించడం) లో సంతకం చేయండి మరియు Eloఆన్లైన్లో ఆడండి, పోటీలలో చేరండి మరియు పరికరాల్లో మీ చరిత్రను సమకాలీకరించండి.",
