  "18gbnrw": "ఈ సైన్-ఇన్ పద్ధతి సర్వర్లో ప్రారంభించబడదు (.Firebase కాన్సోల్  ఆథెన్టిక్  సైన్-ఇన్ పద్ధతి, చూడండి README).",
  "gsmxjw": "బ్రౌజర్ గూగుల్ సైన్-ఇన్ విండోను అడ్డుకుంది. పాప్-అప్లను అనుసరించండి మరియు మళ్ళీ ప్రయత్నించండి.",
