  "nz8c6w": "పాస్ట్ ఎ. PGN / FEN నుండి. chess.com, చెత్త... విశ్లేషించడానికి",
  "uz967d": "పాస్ట్ ది! PGN ఒక ఆట ( నుండి) chess.com, చెత్త...) లేదా FEN స్థానం.",
