  "1ka5efx": "క్వీన్ విజయం",
  "bjyjr1": "తిరిగి వచ్చే కదలిక",
  "19qkfu8": "టిప్ః",
  "47gkh2": "మరియు.",
  "zaagxg": "మూవ్",
  "1ram9jq": "చాలా చిన్న ఆటః ముక్కలు పూర్తిగా అభివృద్ధి చేయబడలేదు. కోట మరియు దాడి చేయడానికి ముందు నైట్స్ మరియు బిషప్లను అభివృద్ధి చేస్తుంది.",
  "yq4m5i": "మధ్య-నిడివి ఆట-రెండు వైపులా ప్రారంభాన్ని దాటింది.",
  "ov5cy": "మీరు ఈ ఆటను కోట చేయలేదు. కాస్టింగ్ రాజును సురక్షితంగా ఉంచి, రూక్ను త్వరగా ప్లేలోకి తీసుకువస్తాడు.",
  "1ud7cw5": "). ప్రారంభ రాణి వేధింపులకు గురై అభివృద్ధి సమయాన్ని ఖర్చు చేస్తుంది.",
  "lom6be": "మిమ్మల్ని చాలా తనిఖీ చేశారు. తనిఖీ చేసినప్పుడు, సురక్షితమైన కదలికలను ఇష్టపడండి మరియు పరుగెత్తేటప్పుడు ముక్కలు పడకుండా ఉండండి.",
  "1pymarz": "మొదటి 8-12 కదలికలలో ఏమ్ నుండి కోట వరకు.",
  "g0chdy": "డెవలపర్ నైట్స్ మరియు బిషప్లు మొదట, రాణి తరువాత.",
  "1bokmkr": "నిష్క్రియాత్మకప్పుడు, పంక్తులు మరియు వాణిజ్య ముక్కలను తెరవాలని చూడండి.",
  "tuqfno": "దాడి సమయంలో, ప్రతి తనిఖీ కదలికను మరియు మీ రాజు యొక్క ప్రతి తప్పించుకోవడం చతురస్రాన్ని తనిఖీ చేయండి.",
  "rddqky": "మీ ప్రయోజనాన్ని కొనసాగించండిః మెటీరియల్లో ముందుకు సాగినప్పుడు, (పుళ్ళను) ఎండ్గేమ్గా సరళీకృతం చేయండి.",
  "38dko8": "ప్రతి ఆట తర్వాత 1-2 కీలక కదలికలను సమీక్షించండి-మీరు వేగంగా మెరుగుపడతారు.",
  "1ynvc81": "అర్ధవంతమైన సమీక్షకు చాలా చిన్నది. తదుపరిసారి మరికొన్ని కదలికలు ఆడండి.",
