  "12y9jbh": "ఈ ఆటను విశ్లేషించవద్దు (.Stockfish లోడ్ చేయడంలో విఫలమైంది).",
  "17gg5ud": "బ్లేండర్లు లేదా తప్పులు లేవు. బాగా ఆడండి!",
  "169i4mj": "సమీక్ష కారణంగా మిస్టేక్ నోట్బుక్ స్థానాలు",
  "1w5ja4f": "యువర్ మిస్టేక్ నోట్బుక్",
