  "12j2upu": "కంప్యూటర్ లేదా ఆన్లైన్లో ఒక ఆటను ప్లే చేయండిః ఆ తర్వాత Stockfish ప్రతి కదలికను గ్రేడ్ చేసి, మీ పొరపాటులను సమీక్షించడానికి వ్యక్తిగత పజిల్స్గా మారుస్తుంది. మీరు ఎంత ఎక్కువగా ఆడతారు, ఇది మీ బలహీనమైన మచ్చలను లక్ష్యంగా చేసుకోవడం మంచిది.",
