  "h0pott": "అన్ని సమీక్షించబడ్డాయి.",
  "tgdyhr": "పెద్ద తప్పు",
  "mvylid": "మీరు ఈ రోజు మొత్తం నోట్బుక్ను సమీక్షించారు!",
