  "1eypr7j": "తగినంత మంచిది కాదుః అది ఇప్పటికీ చాలా ఇస్తుంది. మళ్ళీ ప్రయత్నించండి.",
  "sh25gt": "సోల్వ్, కానీ పొరపాటు/ సూచనతో, కాబట్టి ఈ స్థానం 10 నిమిషాల్లో తిరిగి వస్తుంది.",
