  "7q3i5t": "ప్రత్యర్థి ఖాతా మ్యూట్ చేయడానికి దొరకదు.",
  "1rlm8tp": "ప్రకటనలు మాత్రమే మ్యూట్ చేయగలవు. Firebase నియమాలకు \"మ్యూట్స్\" విభాగం అవసరం.",
