  "186uogz": "కనెక్షన్ మూసివేయబడింది.",
  "blsipv": "మీ ప్రత్యర్థిని చేరుకోలేదుః మీ నెట్వర్క్లలో ఒకటి ప్రత్యక్ష కనెక్షన్లను (మొబైల్ డేటా మరియు పాఠశాల/వి-ఫైపైన సమయం). మళ్ళీ ప్రయత్నించండి లేదా నెట్వర్క్లను మార్చండి.",
  "1immbom": "మీ నెట్వర్క్లు నేరుగా కనెక్ట్ కాలేవు, కాబట్టి ఈ ఆట బ్యాకప్ సర్వర్ ద్వారా నడుస్తుంది (మోవ్స్ కొంచెం నెమ్మదిగా రావచ్చు).",
  "49ijs4": "ప్రత్యర్థి ఎవరూ కనుగొనబడలేదు. కొన్ని నిమిషాల్లో మళ్లీ ప్రయత్నించండి లేదా ఒక స్నేహితుడిని ఫైండ్ మ్యాచ్ కూడా నొక్కమని అడగండి.",
