  "11hparn": "ఖర్జూరాలు",
  "1lrzbkg": "ఇది ఎలా పనిచేస్తుంది",
  "1hhha0z": "ముందుకు సాగండి",
  "1j3szza": "ప్రతి పాఠంలో 3 హృదయాలు ఉంటాయి; ఒక తప్పు చర్య ఖర్చు అవుతుంది. ఎటువంటి తప్పులు లేవు మరియు ఎటువంటి సూచనలు 3 నక్షత్రాలను సంపాదిస్తాయి. మీ పరంపరను కొనసాగించడానికి ప్రతిరోజూ అధ్యయనం చేయండి. ఇప్పటికే ఎలా ఆడాలో తెలుసు? ప్రెస్",
