  "2ehbjo": "లీవ్ పాఠం",
  "sf0r9t": "హార్ట్స్ మిగిలి ఉన్నాయి.",
  "zkouah": "మళ్లీ ప్రయత్నించండి",
  "oqqg2v": "తనిఖీ చేయండి",
  "u7ru84": "అవకాశాలు",
  "7wrzqy": "తిరిగి మార్గం వరకు.",
  "eqgmvb": "అద్భుతమైన!",
