  "16007bo": "సరైన కదలిక కాదు, మళ్ళీ ప్రయత్నించండి!",
  "5aia4c": "సరైన ట్రాక్! నల్ల సమాధానాలు...",
  "ujm4u2": "అది నల్లజాతీయులు తప్పించుకోవడానికి వీలు కల్పిస్తుంది. నల్లజాతీయుడిని నడపడానికి వదిలిపెట్టిన కదలికను కనుగొనండి!",
  "fdz5wz": "ప్రతిష్టంభన! నలుపు రంగుకు ఎటువంటి కదలికలు లేవు-డ్రా.",
  "lbf31c": "ఆట డ్రాగా ముగిసింది.",
