  "1sqbhs3": "రీపీట్ పాస్వర్డ్",
  "mfp3qa": "ఖాతా సృష్టించండి",
  "dekebf": "మీరు ఎవరు?",
  "1ja8kn6": "ప్రారంభం కావడానికి మీ స్థాయిని నొక్కండి. Elo... ఇది ప్రతి ఆటతో పైకి క్రిందికి వెళుతుంది, కాబట్టి నిజాయితీగా ఎంచుకోండి!",
  "17trtp6": "ఎప్పుడూ నియమాలను నేర్చుకోలేదు లేదా నేర్చుకున్నారు.",
  "1h58y91": "ముక్కలు ఎలా కదులుతాయి, కానీ తరచుగా పదార్థాలను కోల్పోతాయి అని తెలుసుకోండి.",
  "qiy3g2": "క్రమం తప్పకుండా, కొన్ని ప్రారంభాలు మరియు ప్రాథమిక వ్యూహాలు తెలుసు.",
  "1nhm0z1": "ఎక్స్పీరియన్స్, ముందుగానే లెక్కించబడుతుంది, అరుదుగా బ్లండర్లు",
  "1ogsmbx": "వ్యూహాలు మరియు ఎండ్గేమ్లలో బలమైనది; క్లబ్లు లేదా టోర్నమెంట్లను ఆడింది.",
  "1xnl61h": "వినియోగదారులు 3-20 అక్షరాలుః అక్షరాలు, అంకెలు మరియు  మాత్రమే",
  "pvxell": "గత పదాలకు కనీసం 6 పాత్రలు అవసరం.",
  "1dy18z7": "పాస్వర్డ్లు సరిపోలవు.",
  "sbm84j": "ఆ వినియోగదారు పేరు తీసుకోబడుతుంది.",
  "pu45nl": "\"అడ్మిన్\" తో ప్రారంభమయ్యే పేర్లు యజమాని కోసం కేటాయించబడతాయి, మరొకటి ఎంచుకోండి.",
  "cm2eu8": "వాంగ్ వినియోగదారు పేరు లేదా పాస్వర్డ్",
  "1bcboik": "చాలా ప్రయత్నాలు, ఒక క్షణం వేచి ఉండి మళ్లీ ప్రయత్నించండి.",
  "1z0iker": "సర్వర్కు చేరుకోలేము. మీ ఇంటర్నెట్ కనెక్షన్ను చూడండి.",
  "s7k1k6": "సర్వర్ ఇమెయిల్/పాస్వర్డ్ సైన్-ఇన్ (చూడండి README) ను ప్రారంభించలేదు.",
  "1aeatdo": "సర్వర్ యాక్సెస్ను ఖండించింది; తనిఖీ చేయండి Firebase నియమాలు (చూడండి) README).",
