  "1dw5u8l": "దుర్వినియోగం/స్పామ్ కోసం తిరుగుబాటు",
  "txi5dc": "గ్రాంట్ శీర్షిక (జిఎం, ఐఎం,...)",
  "9gmdzn": "రెవోక్",
  "1kkwiq4": "ప్రకటన చేయండి",
  "h9scvb": "సరిపోలే ఆటగాళ్ళు లేరు.",
  "jtga8m": "అబుష్/స్పామ్ ఇన్ చాట్",
  "a084df": "యజమాని అడ్మిన్ హక్కులను మంజూరు చేస్తాడు/నిర్వహిస్తాడు. అడ్మిన్స్ ఆన్లైన్ ఆటలలో హింట్ను ఉపయోగించవచ్చు (తీవ్రిస్తారు) మరియు డబ్బాలో ఉండవచ్చు.",
  "h2j6ym": "ఎడిఎంఎన్ ఖాతా మాత్రమే ఉంది. మరికొందరు సైన్ అప్ చేసి, ఒకసారి సైట్ను తెరిచిన తర్వాత ఇక్కడ కనిపిస్తారు.",
  "b24ybq": "సర్వర్ ద్వారా తిరస్కరించబడిందిః యజమాని మరియు అడ్మిన్స్ మాత్రమే టైటిల్స్ మంజూరు చేయవచ్చు. కొత్తది Firebase నియమాలు (శీర్షికల విభాగం) మరియు పబ్లిష్.",
  "14039ix": "ఒక ప్రకటనగా, మీరు ఆటగాళ్లను మ్యూట్ చేయవచ్చు, టైటిల్స్ మంజూరు చేయవచ్చు లేదా తొలగించవచ్చు మరియు సైట్-వైడ్ ప్రకటనలను పోస్ట్ చేయవచ్చు. మీరు ఇతర అడ్మిరల్లను లేదా యజమానిని మ్యూట్ చేయలేరు.",
  "xeu5nn": "ఎర్రోర్, మళ్ళీ ప్రయత్నించండి. కొత్తదాన్ని ప్రచురించండి. Firebase నియమాలు (శీర్షికల విభాగం).",
  "9nsy4a": "బానిసలు/ యజమాని మాత్రమే మ్యూట్ చేయగలడు. కొత్తదాన్ని పాస్ చేయండి. Firebase నియమాలు (ముట్లు) మరియు పబ్లిష్.",
  "1bqp7v7": "సర్వర్ ద్వారా తిరస్కరించబడిందిః కొత్త Firebase నియమాలను (\"అడ్మిన్స్ తో) మరియు ప్రెస్ పబ్లిష్ను అతికించండి.",
  "15hetzv": "లోకల్ మోడ్ః ఈ బ్రౌజర్లో సృష్టించబడిన ఖాతాలు మాత్రమే జాబితా చేయబడ్డాయి (అనేబుల్). Firebase: చూడండిః README).",
  "nce8v2": "అడ్మిన్ జాబితాను చదవలేదుః కొత్తదాన్ని అతికించండి Firebase నియమాలు (\"అడ్మిన్స్ తో) మరియు ప్రెస్ పబ్లిష్. అప్పటి వరకు గ్రాంట్/రివివ్ పని చేయదు.",
  "1jxoxrh": "మీ ఇంటర్నెట్ కనెక్షన్ను చూడండి.",
