  "qgn2b0": "మీ చివరి ఆట నుండి టర్నింగ్ పాయింట్, పాఠం మరియు వ్యాయామం",
  "3l7pne": "నేను ఎక్కడ తప్పు చేస్తాను మరియు దానిని ఎలా పరిష్కరించాలి?",
  "1uhdc4j": "మీ స్థాయి కోసం 30 నిమిషాల ప్రణాళిక",
