  "163x8ot": "మీకు సరిపోయే ఓపెన్లు",
  "19afa4y": "మీ విశ్లేషించిన ఆటల నుండి వచ్చే అవకాశం",
  "1cr8sey": "మీ రోడ్మ్యాప్ నుండి ఒక చిన్న ప్రణాళిక",
