  "9iutkl": "మీ కోచ్ను సందేశం...",
  "9otk9o": "శోధనః పిన్, పాస్ బంటు, లూసెనా, సిసిలియన్, ఛాంపియన్లు...",
  "tg9zcq": "ఆన్లైన్  కదలికలను తనిఖీ చేయండి Stockfish 19",
  "17arc2s": "మీ పరికరంలో Stockfish 19 తో ప్రాథమిక మోడ్  రోగనిర్ధారణ",
  "13xgj41": "సర్వర్ బిజీగా మరియు ప్రాథమిక మోడ్, ఒక నిమిషంలో తిరిగి ప్రారంభమవుతుంది",
  "15os6p5": "Stockfish 19 ఆ స్థానాన్ని విశ్లేషించడం.",
  "1nz0wc8": "Stockfish 19 తో ఆటను సమీక్షించండి.",
  "1g05rlg": "Stockfish 19 ఆటను విశ్లేషించడం...",
  "ysr3dx": "విశ్లేషణ చేసిన స్థానం",
  "sohiq3": "ఎండ్గేమ్ స్థానం",
  "uisqqq": "కనీసం 2 ఆటలు విశ్లేషించబడ్డాయి. Stockfish 19 రోగనిర్ధారణ కోసం అవసరం.",
  "1agn2qt": "విశ్లేషించబడలేదు.",
  "1czlgy0": "అన్ని విశ్లేషణ మీ పరికరంలో నడుస్తుంది (.Stockfish 19 మరియు నాలెడ్జ్ లైబ్రరీ). ఏ డేటా ఎక్కడా పంపబడదు.",
  "fd9h5j": "నోలెడ్జ్ లైబ్రరీ, మీ ఆటలు, లైచెస్/Stockfish విశ్లేషణ మరియు ఎండ్గేమ్ టేబుల్బేస్ను సమాధానానికి ముందు చూడండి.",
  "1cdmx13": "మీ ప్రశ్న మరియు ఆట డేటా దీనికి సమాధానం ఇవ్వడానికి అవసరం (.Eloబలహీనతలు, కదలికలు) గూగుల్ యొక్క జెమిని 3.5 ఫ్లాష్-లైట్ AI సర్వర్కు పంపబడతాయి; విశ్లేషించడానికి స్థానాలు లైచెస్కు పంపబడతాయి. గేమ్ విశ్లేషణ ఇప్పటికీ మీ పరికరంలో నడుస్తుంది. Stockfish.",
  "n1rbln": "నోలెడ్జ్ లైబ్రరీని శోధించడం",
  "1dm4sld": "మీ ఆట ప్రొఫైల్ను చదవడం",
  "1bteoar": "ఇటీవలి ఆటలను తనిఖీ చేయండి.",
  "2zheq8": "బోర్డు వైపు చూడండి.",
  "n2xnlx": "ఆ స్థానాన్ని విశ్లేషించడం.",
  "1de8xv0": "ఎండ్గేమ్ టేబుల్బేస్ను తనిఖీ చేయడం",
  "5x3mf4": "టాప్.",
  "bwnkkn": "AI సర్వర్ ప్రస్తుతం స్పందించడం లేదు.",
  "o58ol5": "కోచ్ ప్రాథమిక మోడ్ను ఉపయోగిస్తాడు మరియు సర్వర్ను సుమారు ఒక నిమిషంలో తిరిగి నియమించుకుంటాడు.",
  "eaw9me": "ఆఫ్లైన్ AI",
  "1nmgqnh": "మీరు కొంచెం వేగంగా అడుగుతున్నారు, దయచేసి ఒక నిమిషం వేచి ఉండండి.",
