  "8hftgk": "కథనాన్ని చదవండి",
  "cqj91m": "ప్రాథమిక విధానం.",
  "1k53ue6": "ప్రారంభాలు, ఎండ్గేమ్స్, వ్యూహాలు, మీ చివరి ఆట గురించి అడగండి...",
  "1iua6tc": "శోధనః పిన్, పాస్ బంటు, లూసెనా, సిసిలియన్...",
  "9jdciv": "కోచ్ మీ పరికరంలో పరుగెత్తుతూ, మీ పరికరాన్ని ఉపయోగిస్తాడు. Stockfish- విశ్లేషించిన ఆటలు మరియు నాలెడ్జ్ లైబ్రరీ. ఏ డేటా ఎక్కడైనా పంపబడదు.",
  "s82k5t": "నాలెడ్జ్ లైబ్రరీలో నేను కనుగొన్నది ఇక్కడ ఉందిః",
  "1i207lp": "వ్యాసాలు దొరకలేదు. మరొక మాట ప్రయత్నించండి.",
  "1c9gr42": "మేటింగ్ నమూనాలు",
  "1h0k7yc": "స్ట్రాటజీ",
  "igop6o": "నియమాలు",
  "xv108d": "కోచ్ ఇంకా సమాధానం ఇస్తున్నారు, దయచేసి వేచి ఉండండి.",
  "dfet3": "ప్రారంభ దశ",
  "1rycwyy": "మధ్య దశ",
  "1m4vlhv": "చరిత్రలో ఆటలు.",
  "1qrb6jn": "గేమ్స్ విశ్లేషించబడ్డాయి.",
  "18gpotu": "స్కోరు (విన్స్  12 డ్రాలు)",
  "1hcr7kl": "నేను ఎందుకు ఓడిపోతాను?",
  "8haj3w": "ఈ రోజు నేను ఏమి అభ్యసించాలి?",
  "rohzmq": "నేను ఏ ఓపెనింగ్స్ ఆడాలి?",
  "wsl5ck": "నా బలాలు ఏమిటి?",
  "e9np47": "నేను ఎలా పొందుతాను? Elo?",
  "1ntjuzp": "ప్రారంభాలు, ఎండ్గేమ్స్, వ్యూహాలు, Elo...",
  "1sobq2r": "కోచ్ కోసం ప్రశ్న",
  "1rrbpqr": "ఆయన! నేను Royal Gambit కోచ్. ఒక ప్రశ్నను దిగువ చేయండి లేదా మీ స్వంతంగా టైప్ చేయండి.",
  "1rk2ky1": "కోచ్ మీ పరికరంలో పరుగెత్తతాడు, గ్రేడ్ చేసిన ఆటలను ఉపయోగించి. Stockfish... ఏ డేటా మీ పరికరాన్ని వదిలివేయలేదు.",
  "qdtc3v": "నాకు అది రాలేదు. దిగువ సూచించిన ప్రశ్నలలో ఒకదాన్ని ప్రయత్నించండి.",
  "1omag1": "ఓపెన్ యూనిట్",
  "2g0ssl": "సోల్వ్ పజిల్స్",
