  "vxg1qz": "వ్యూ పొజిషన్",
  "1hhnc0o": "సోల్వ్ వ్యూహాలు పజిల్స్",
  "kywp95": "పజిల్స్ః వ్యూహాలు",
  "mu24i1": "పజిల్స్ః సంభోగ నమూనాలు",
  "inc1gc": "పజిల్స్ః ఎండ్గేమ్స్",
  "puq9pn": "రైలు నమూనా గుర్తింపుః రోజుకు 3-5 పజిల్స్.",
  "16mjsem": "సమీక్ష ది లూసెనా మరియు ఫిలిడర్ స్థానాలు",
  "1cqu2d": "రెండు అత్యంత ముఖ్యమైన రూక్ ఎండ్గేమ్స్, మరియు అవి అన్ని సమయాల్లో వస్తాయి.",
  "1nw0mw3": "కదలికల ద్వారా అడుగు పెట్టండి, అప్పుడు మీరు చూడకుండా ఆడగలిగే వరకు \"ప్రాక్టైజ్ వర్సెస్ కంప్యూటర్\".",
  "19r7bzs": "1800 కంటే తక్కువ ఆటలను వ్యూహాలు నిర్ణయిస్తాయి. Elo.",
  "dhgblm": "మీరు ఇప్పుడే నేర్చుకున్న వాటిని ఉపయోగించండి. ఆట తర్వాత ప్రతి కదలిక గ్రేడ్ చేయబడుతుంది కాబట్టి కోచ్ మీకు బాగా తెలుసు.",
  "19slj1z": "సమీక్ష కారణంగా మీ స్వంత తప్పుల నుండి తీసుకున్న అభిప్రాయాలు.",
  "95m2k0": "ఈ యూనిట్ లాక్ చేయబడిందిః అన్లాక్ పరీక్ష రాయడానికి లేదా మునుపటి యూనిట్లను పూర్తి చేయడానికి \"జంప్\" నొక్కండి.",
  "13f7mw9": "మీరు ఈ యూనిట్ను పూర్తి చేశారు. సమీక్షకు గుణపాఠాన్ని ఇవ్వండి.",
  "rqm9es": "ఏమీ కోల్పోవడం",
  "1hkj0ll": "తప్పిపోయిన వ్యూహాలు",
  "1mxnz9u": "తప్పిపోయిన సహచరులు",
  "1nkq9ny": "షాక్ ఓపెనింగ్స్",
  "zxdqp2": "సురక్షితం కాని రాజు",
  "1nya24f": "ప్రణాళికలేని మిడిల్గేమ్స్",
  "18rkemf": "కన్వర్టింగ్/ఎండ్గేమ్స్",
  "299hn": "యాప్ ఇన్‌స్టాల్ చేయండి",
  "1nhw4vj": "ఒక యాప్గా మొత్తం Royal Gambit",
  "vl8raf": "మొత్తం Royal Gambit",
  "19mx570": "మీ హోమ్ స్క్రీన్ నుండి యాప్, పూర్తి స్క్రీన్ లాగా తెరిచి, కంప్యూటర్ను ఆఫ్లైన్గా ప్లే చేయండి.",
