  "lz65mo": "మరిన్ని",
  "1qcgha8": "ఫోన్ మరియు కంప్యూటర్లో యాప్గా ఉపయోగించండి.",
  "nchtna": "ఐఫోన్/ప్యాప్ (సఫారి)",
