  "4el6o6": "పేరు",
  "1p6iil1": "చివరి క్రియాశీలత",
  "dr4ghz": "ఏదో తప్పు జరిగింది, మళ్ళీ ప్రయత్నించండి.",
  "fznq4a": "Royal Gambit లో ఒక ఆట",
  "txz6za": "ఈ లింక్ను కాపీ చేయండి, ఆపై క్రోమ్/ఫారిలో తెరవండిః",
  "19diupy": "ఈ యాప్",
  "dhydzk": "వైన్ ఆటలు కూడా సమీక్షించడం విలువైనవిః మీ ప్రత్యర్థి మెరుగైన రక్షించగల 1-2 ప్రదేశాలను కనుగొనండి, కాబట్టి మీ తదుపరి దాడి మరింత దృఢంగా ఉంటుంది.",
