  "m2bcgo": "షేర్",
  "cpgsda": "సఫారి దిగువ బార్లో బటన్",
  "w4fyow": "చోస్",
  "jhzwo8": "హోమ్ స్క్రీన్ను జోడించండి.",
  "3sqet": "ఃః Royal Gambit ఐకాన్ మీ ఇంటి తెరపై కనిపిస్తుంది.",
