  "gvhd2a": "లేదా మెనూ",
  "fum7jr": "యాప్లు  ఈ సైట్ను ఏర్పాటు చేయండి",
  "lvdbub": "ఏదైనా Elo.",
  "1dr8l1t": "ఇప్పుడు చెక్మేట్!",
  "1l83onw": "ఆటలు.",
  "1mbhjmd": "స్కోర్",
  "k0iu34": "సోల్వ్",
  "ike325": "సమీక్ష ఇప్పుడు",
  "1wltjbu": "చెక్మేట్",
