  "afymmh": "ఆ తర్వాత మీరు చాప్ చేశారు. {0} కదలికలు. మీ రాజు భద్రతను చూడండి.",
  "16wl0li": "{0} తర్వాత చెక్మేట్ ద్వారా గెలిచింది. {1} కదలికలు.",
