  "1u62nm7": "{0} యొక్క సుదీర్ఘ ఆటః మిడిల్గేమ్/ఎండ్గేమ్లో నిజమైన పోరాటం.",
  "ias0r0": "{0} కోట కాదు-రాజు మధ్యలో బహిర్గతమవుతుంది.",
  "nh1uds": "{0} రాణిని చాలా ముందుగానే బయటకు తీసుకువచ్చింది (మోవ్) {1}:",
