  "f9wd9u": "మీ ప్రత్యర్థి తమ రాణిని కోల్పోయాడు. {0} బాగా తీసుకోండి.",
  "1p78pe4": "{0} ఈ ఆటలో తనిఖీలు-ఒక పదునైన, దాడి చేసే ఆట.",
  "15j0cw6": "మెటీరియల్కు అనుకూలంగా ఉంది. {0} ({1}–{2} కఠినమైన గణన ద్వారా).",
  "byijl7": "గుర్తించదగినదిః {0} రాణిని ఒక చిన్న ముక్క కోసం వర్తకం చేశారు.",
